'use client';

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import Link from 'next/link';
import { Button } from '@/components/ui/button';
import { 
  Gavel, 
  Clock, 
  TrendingUp, 
  Flame,
  ArrowRight,
  Zap,
  Users,
  Eye,
  ChevronRight
} from 'lucide-react';
import { apiClient } from '@/lib/api/client';
import { useTheme } from '@/lib/context/ThemeContext';

interface Auction {
  _id: string;
  startingBidEth: number;
  currentBidEth: number;
  timeRemainingMs: number;
  totalBids: number;
  uniqueBidders: number;
  eventId: {
    _id: string;
    title: string;
    date: string;
    image?: string;
    imageUrl?: string;
  };
  ticketTypeId: {
    name: string;
  };
  minNextBidEth: number;
}

export function LiveAuctionsSection() {
  const { theme } = useTheme();
  const isDark = theme === 'dark';
  const [auctions, setAuctions] = useState<Auction[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchAuctions();
  }, []);

  const fetchAuctions = async () => {
    try {
      const data = await apiClient.getAuctions({ status: 'active', limit: 6 });
      if (data.success) {
        setAuctions(data.auctions || []);
      }
    } catch (err) {
      console.error('Failed to fetch auctions:', err);
    } finally {
      setLoading(false);
    }
  };

  const formatTime = (ms: number): string => {
    if (ms <= 0) return 'Ended';
    const seconds = Math.floor(ms / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);
    const days = Math.floor(hours / 24);
    
    if (days > 0) return `${days}d ${hours % 24}h`;
    if (hours > 0) return `${hours}h ${minutes % 60}m`;
    if (minutes > 0) return `${minutes}m`;
    return `${seconds}s`;
  };

  // Don't render if no auctions
  if (!loading && auctions.length === 0) {
    return null;
  }

  return (
    <section className={`py-20 ${isDark ? 'bg-[#0D0D0D]' : 'bg-gray-50'}`}>
      <div className="container mx-auto px-4 max-w-7xl">
        {/* Section Header */}
        <div className="flex flex-col md:flex-row md:items-end md:justify-between gap-4 mb-10">
          <div>
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-gradient-to-r from-orange-500/20 to-amber-500/20 border border-orange-500/30 mb-4"
            >
              <Gavel className="h-4 w-4 text-orange-400" />
              <span className="text-sm font-medium text-orange-400">Live Auctions</span>
              <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse" />
            </motion.div>
            
            <motion.h2
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ delay: 0.1 }}
              className={`text-3xl md:text-4xl font-bold ${isDark ? 'text-white' : 'text-gray-900'}`}
            >
              Bid on{' '}
              <span className="bg-gradient-to-r from-orange-400 to-amber-400 bg-clip-text text-transparent">
                Exclusive Tickets
              </span>
            </motion.h2>
            
            <motion.p
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ delay: 0.2 }}
              className={`mt-2 ${isDark ? 'text-gray-400' : 'text-gray-600'}`}
            >
              Secure your spot at sold-out events with ETH bidding
            </motion.p>
          </div>

          <motion.div
            initial={{ opacity: 0, x: 20 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
          >
            <Link href="/auction">
              <Button 
                variant="outline" 
                className={`group ${isDark ? 'border-orange-500/50 text-orange-400 hover:bg-orange-500/10' : 'border-orange-500 text-orange-600 hover:bg-orange-50'}`}
              >
                View All Auctions
                <ChevronRight className="h-4 w-4 ml-1 group-hover:translate-x-1 transition-transform" />
              </Button>
            </Link>
          </motion.div>
        </div>

        {/* Loading State */}
        {loading ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {[1, 2, 3].map((i) => (
              <div 
                key={i} 
                className={`h-80 rounded-2xl animate-pulse ${isDark ? 'bg-white/5' : 'bg-gray-200'}`} 
              />
            ))}
          </div>
        ) : (
          /* Auctions Grid */
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {auctions.slice(0, 6).map((auction, index) => (
              <AuctionMiniCard key={auction._id} auction={auction} index={index} />
            ))}
          </div>
        )}

        {/* CTA Banner */}
        {!loading && auctions.length > 0 && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            className={`mt-12 p-6 md:p-8 rounded-2xl relative overflow-hidden ${
              isDark 
                ? 'bg-gradient-to-r from-orange-950/50 to-amber-950/50 border border-orange-500/20' 
                : 'bg-gradient-to-r from-orange-100 to-amber-100 border border-orange-200'
            }`}
          >
            {/* Background glow */}
            <div className="absolute top-0 right-0 w-64 h-64 bg-orange-500/20 rounded-full blur-[100px]" />
            
            <div className="relative flex flex-col md:flex-row items-center justify-between gap-6">
              <div className="flex items-center gap-4">
                <div className="p-4 rounded-2xl bg-gradient-to-br from-orange-500 to-amber-500 shadow-lg shadow-orange-500/30">
                  <Gavel className="h-8 w-8 text-white" />
                </div>
                <div>
                  <h3 className={`text-xl font-bold ${isDark ? 'text-white' : 'text-gray-900'}`}>
                    Have a ticket to sell?
                  </h3>
                  <p className={`${isDark ? 'text-gray-400' : 'text-gray-600'}`}>
                    List your ticket for auction and let buyers compete
                  </p>
                </div>
              </div>
              
              <Link href="/my-tickets">
                <Button 
                  size="lg"
                  className="bg-gradient-to-r from-orange-500 to-amber-500 hover:from-orange-600 hover:to-amber-600 text-white font-semibold px-8 border-0 shadow-lg shadow-orange-500/25"
                >
                  <Zap className="h-5 w-5 mr-2" />
                  Start Auction
                </Button>
              </Link>
            </div>
          </motion.div>
        )}
      </div>
    </section>
  );
}

// Mini Auction Card for homepage - Zomato District Style
function AuctionMiniCard({ auction, index }: { auction: Auction; index: number }) {
  const { theme } = useTheme();
  const isDark = theme === 'dark';
  const [timeRemaining, setTimeRemaining] = useState(auction.timeRemainingMs);

  useEffect(() => {
    if (timeRemaining <= 0) return;
    const interval = setInterval(() => {
      setTimeRemaining(prev => Math.max(0, prev - 1000));
    }, 1000);
    return () => clearInterval(interval);
  }, [timeRemaining]);

  const formatTime = (ms: number): string => {
    if (ms <= 0) return 'Ended';
    const seconds = Math.floor(ms / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);
    const days = Math.floor(hours / 24);
    
    if (days > 0) return `${days}d ${hours % 24}h`;
    if (hours > 0) return `${hours}h ${minutes % 60}m`;
    if (minutes > 0) return `${minutes}m ${seconds % 60}s`;
    return `${seconds}s`;
  };

  const formatDate = (dateStr: string) => {
    if (!dateStr) return 'TBD';
    const date = new Date(dateStr);
    return date.toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' });
  };

  const isEndingSoon = timeRemaining > 0 && timeRemaining < 60 * 60 * 1000;
  const isHot = auction.totalBids >= 5 || auction.uniqueBidders >= 3;
  const hasNoBids = auction.currentBidEth === 0;
  const eventImage = auction.eventId?.image || auction.eventId?.imageUrl || '/placeholder-event.jpg';

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ delay: index * 0.1 }}
      whileHover={{ y: -4, scale: 1.01 }}
      className="h-full"
    >
      <Link href={`/auction/${auction._id}`} className="block h-full">
        <div className={`
          relative overflow-hidden rounded-2xl h-full
          ${isDark 
            ? 'bg-[#1A1A1A] border border-white/10' 
            : 'bg-white border border-gray-100 shadow-lg shadow-black/5'
          }
          transition-all duration-300 hover:shadow-xl
          ${isDark ? 'hover:border-orange-500/30' : 'hover:shadow-orange-500/10'}
        `}>
          
          {/* Hero Image */}
          <div className="relative h-44 overflow-hidden">
            <img
              src={eventImage}
              alt={auction.eventId?.title || 'Event'}
              className="w-full h-full object-cover"
            />
            <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-black/20" />
            
            {/* Top badges */}
            <div className="absolute top-3 left-3 right-3 flex items-start justify-between">
              <div className="flex flex-wrap gap-1.5">
                {timeRemaining > 0 && (
                  <div className="flex items-center gap-1 px-2 py-0.5 rounded-full bg-green-500/90">
                    <span className="w-1.5 h-1.5 rounded-full bg-white animate-pulse" />
                    <span className="text-[9px] font-bold text-white">LIVE</span>
                  </div>
                )}
                {hasNoBids && (
                  <div className="px-2 py-0.5 rounded-full bg-emerald-500/90">
                    <span className="text-[9px] font-bold text-white">NO BIDS YET</span>
                  </div>
                )}
                {isEndingSoon && (
                  <div className="px-2 py-0.5 rounded-full bg-red-500/90 animate-pulse">
                    <span className="text-[9px] font-bold text-white">ENDING SOON</span>
                  </div>
                )}
                {isHot && !isEndingSoon && (
                  <div className="flex items-center gap-1 px-2 py-0.5 rounded-full bg-gradient-to-r from-orange-500 to-amber-500">
                    <Flame className="h-2.5 w-2.5 text-white" />
                    <span className="text-[9px] font-bold text-white">HOT</span>
                  </div>
                )}
              </div>
              <div className="flex items-center gap-1 px-1.5 py-0.5 rounded-full bg-black/50">
                <Eye className="h-2.5 w-2.5 text-white/80" />
                <span className="text-[9px] text-white/80">{auction.views || 0}</span>
              </div>
            </div>

            {/* Event info overlay */}
            <div className="absolute bottom-0 left-0 right-0 p-3">
              <div className="inline-flex px-2 py-0.5 rounded-full bg-white/95 mb-1.5">
                <span className="text-[10px] font-semibold text-gray-800">
                  {auction.ticketTypeId?.name || 'General Admission'}
                </span>
              </div>
              <h3 className="text-base font-bold text-white leading-tight mb-1 drop-shadow-lg line-clamp-1">
                {auction.eventId?.title || 'Event'}
              </h3>
              <div className="flex items-center gap-2 text-white/80 text-[10px]">
                <span className="flex items-center gap-0.5">
                  <Clock className="h-2.5 w-2.5" />
                  {formatDate(auction.eventId?.date)}
                </span>
              </div>
            </div>
          </div>

          {/* Card content */}
          <div className="p-3 space-y-3">
            {/* Bid amount */}
            <div className="flex items-center justify-between">
              <div>
                <p className={`text-[10px] ${isDark ? 'text-gray-500' : 'text-gray-500'}`}>
                  {hasNoBids ? 'Starting Bid' : 'Current Bid'}
                </p>
                <div className="flex items-center gap-1.5">
                  <div className={`p-1 rounded ${isDark ? 'bg-green-500/20' : 'bg-green-50'}`}>
                    <TrendingUp className="h-3 w-3 text-green-500" />
                  </div>
                  <span className={`text-lg font-bold ${isDark ? 'text-white' : 'text-gray-900'}`}>
                    {hasNoBids ? auction.startingBidEth?.toFixed(4) : auction.currentBidEth?.toFixed(4)}
                  </span>
                  <span className="text-xs font-semibold text-orange-500">ETH</span>
                </div>
              </div>
            </div>

            {/* Timer */}
            <div className={`
              flex items-center justify-between px-2.5 py-2 rounded-lg
              ${isEndingSoon 
                ? 'bg-red-500/10 border border-red-500/20' 
                : isDark ? 'bg-white/5' : 'bg-gray-50'
              }
            `}>
              <span className={`text-[10px] ${isDark ? 'text-gray-500' : 'text-gray-500'}`}>Ends in</span>
              <span className={`text-sm font-bold font-mono ${isEndingSoon ? 'text-red-500' : isDark ? 'text-white' : 'text-gray-900'}`}>
                {formatTime(timeRemaining)}
              </span>
            </div>

            {/* Stats */}
            <div className="flex items-center gap-3 text-[10px]">
              <span className={`flex items-center gap-1 ${isDark ? 'text-gray-500' : 'text-gray-500'}`}>
                <Gavel className="h-3 w-3 text-orange-500" />
                {auction.totalBids || 0} Bids
              </span>
              <span className={`flex items-center gap-1 ${isDark ? 'text-gray-500' : 'text-gray-500'}`}>
                <Users className="h-3 w-3 text-purple-500" />
                {auction.uniqueBidders || 0} Bidders
              </span>
            </div>

            {/* Button */}
            <Button 
              className="w-full h-10 bg-gradient-to-r from-orange-500 to-orange-600 hover:from-orange-600 hover:to-orange-700 text-white text-sm font-bold rounded-xl border-0 shadow-md shadow-orange-500/20"
            >
              <Zap className="h-3.5 w-3.5 mr-1.5" />
              Place Bid
              <ArrowRight className="h-4 w-4 ml-1" />
            </Button>
          </div>
        </div>
      </Link>
    </motion.div>
  );
}
